import { useRef, type HTMLAttributes, type Key, type ReactNode, type Ref } from 'react';
import { cn } from '../../utils/cn';
import { Popover, PopoverContent, PopoverTrigger } from '../popover';
import { overflowListVariants, type OverflowListVariantProps } from './overflow-list.variants';
import { useFitCount } from './useFitCount';

export interface OverflowListLabels {
  /** Visible text of the chip trigger ("+3 more"); avatars show "+3" and use this as the name. */
  more: (count: number) => string;
  /** Accessible name and heading of the popover ("3 more"). */
  title: (count: number) => string;
}

const DEFAULT_LABELS: OverflowListLabels = {
  more: (n) => `+${n} more`,
  title: (n) => `${n} more`,
};

export interface OverflowListProps<T> extends Omit<HTMLAttributes<HTMLDivElement>, 'className' | 'children'>, OverflowListVariantProps {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  items: readonly T[];
  /** Renders one visible item (a chip, an Avatar…). */
  renderItem: (item: T, index: number) => ReactNode;
  /** Renders a hidden item inside the popover; defaults to `renderItem`. */
  renderOverflowItem?: (item: T, index: number) => ReactNode;
  /** Stable key per item; defaults to the index. */
  getKey?: (item: T, index: number) => Key;
  /** Show at most this many items. */
  max?: number;
  /** Also fit to the available width (ResizeObserver); `max` still caps it. */
  responsive?: boolean;
  /** Accessible name of the list (e.g. "Labels"). */
  label?: string;
  /** Built-in strings (English defaults). */
  labels?: Partial<OverflowListLabels>;
}

/**
 * A row of items that stops at `max` (or at the available width with `responsive`) and ends
 * with a "+N more" button that opens a Popover listing the rest. Works for chips and avatars.
 */
export function OverflowList<T>({
  items,
  renderItem,
  renderOverflowItem,
  getKey = (_item, i) => i,
  max,
  responsive = false,
  label,
  labels: labelsProp,
  variant,
  className,
  ...props
}: OverflowListProps<T>) {
  const labels = { ...DEFAULT_LABELS, ...labelsProp };
  const containerRef = useRef<HTMLDivElement>(null);
  const measureRef = useRef<HTMLDivElement>(null);
  const fit = useFitCount(responsive, containerRef, measureRef, items.length);
  const visibleCount = Math.max(0, Math.min(items.length, max ?? Infinity, fit ?? Infinity));
  const hidden = items.slice(visibleCount);
  const s = overflowListVariants({ variant });
  const triggerText = (n: number) => (variant === 'avatar' ? `+${n}` : labels.more(n));

  return (
    <div ref={containerRef} className={cn(s.root(), className)} {...props}>
      <ul aria-label={label} className={s.list()}>
        {items.slice(0, visibleCount).map((item, i) => (
          <li key={getKey(item, i)} className={s.item()}>
            {renderItem(item, i)}
          </li>
        ))}
        {hidden.length > 0 && (
          <li className={s.item()}>
            <Popover>
              <PopoverTrigger className={s.trigger()} aria-label={variant === 'avatar' ? labels.more(hidden.length) : undefined}>
                {triggerText(hidden.length)}
              </PopoverTrigger>
              <PopoverContent padding="none" align="start" aria-label={labels.title(hidden.length)} className={s.popup()}>
                <div aria-hidden className={s.popupTitle()}>
                  {labels.title(hidden.length)}
                </div>
                <ul className={s.popupList()}>
                  {hidden.map((item, j) => {
                    const i = visibleCount + j;
                    return (
                      <li key={getKey(item, i)} className={s.popupItem()}>
                        {(renderOverflowItem ?? renderItem)(item, i)}
                      </li>
                    );
                  })}
                </ul>
              </PopoverContent>
            </Popover>
          </li>
        )}
      </ul>
      {responsive && (
        <div ref={measureRef} aria-hidden inert className={s.measure()}>
          {items.map((item, i) => (
            <div key={getKey(item, i)} className={s.item()}>
              {renderItem(item, i)}
            </div>
          ))}
          <span className={s.trigger()}>{triggerText(Math.max(1, items.length))}</span>
        </div>
      )}
    </div>
  );
}

export { OverflowList, type OverflowListProps, type OverflowListLabels } from './OverflowList';
export { useFitCount } from './useFitCount';
export { overflowListVariants, type OverflowListVariantProps } from './overflow-list.variants';
export { doc as overflowListDoc } from './OverflowList.doc';

import { tv, type VariantProps } from '../../utils/tv';

export const overflowListVariants = tv({
  slots: {
    root: 'relative min-w-0',
    list: 'm-0 flex list-none flex-nowrap items-center p-0',
    item: 'shrink-0',
    measure: 'invisible pointer-events-none absolute start-0 top-0 flex h-0 w-max flex-nowrap items-center overflow-hidden',
    trigger: [
      'inline-flex shrink-0 items-center justify-center font-medium text-muted-foreground transition-colors select-none',
      'hover:bg-secondary hover:text-foreground data-popup-open:bg-secondary data-popup-open:text-foreground',
      'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-focus-ring',
    ],
    popup: 'max-h-72 w-60 overflow-y-auto p-1.5',
    popupTitle: 'px-2 pt-1 pb-1.5 font-mono text-[10px] tracking-[0.12em] text-muted-foreground uppercase',
    popupList: 'm-0 grid list-none gap-0.5 p-0',
    popupItem: 'flex min-h-8 items-center gap-2 rounded-md px-2 text-[13px] text-foreground',
  },
  variants: {
    variant: {
      chip: {
        list: 'gap-1.5',
        measure: 'gap-1.5',
        trigger: 'h-6 rounded-md border border-border bg-card px-2 text-[11.5px]',
      },
      avatar: {
        list: '-space-x-2.5',
        measure: '-space-x-2.5',
        trigger: 'relative size-8 rounded-full bg-secondary text-[11px] font-semibold ring-2 ring-card',
      },
    },
  },
  defaultVariants: { variant: 'chip' },
});

export type OverflowListVariantProps = VariantProps<typeof overflowListVariants>;

import { useEffect, useState, type RefObject } from 'react';

/**
 * How many leading items fit in `container`, measuring an off-screen copy in `measure` whose
 * last child is the "+N" trigger template. `undefined` until measured (or when disabled).
 */
export function useFitCount(enabled: boolean, container: RefObject<HTMLElement | null>, measure: RefObject<HTMLElement | null>, count: number) {
  const [fit, setFit] = useState<number | undefined>(undefined);

  useEffect(() => {
    const box = container.current;
    const layer = measure.current;
    if (!enabled || !box || !layer || typeof ResizeObserver === 'undefined') return;

    const compute = () => {
      const kids = Array.from(layer.children) as HTMLElement[];
      const trigger = kids.pop();
      const available = box.clientWidth;
      const rects = kids.map((k) => k.getBoundingClientRect());
      const first = rects[0];
      const second = rects[1];
      const triggerWidth = trigger?.getBoundingClientRect().width ?? 0;
      if (!first) return setFit(0);
      const ltr = getComputedStyle(layer).direction !== 'rtl';
      const spacing = second ? (ltr ? second.left - first.right : first.left - second.right) : 0;
      const extent = (n: number) => {
        const last = rects[n - 1];
        if (!last) return 0;
        return ltr ? last.right - first.left : first.right - last.left;
      };
      let n = rects.length;
      if (extent(n) > available) {
        n = rects.length - 1;
        while (n > 0 && extent(n) + spacing + triggerWidth > available) n--;
      }
      setFit(n);
    };

    const observer = new ResizeObserver(compute);
    observer.observe(box);
    return () => observer.disconnect();
  }, [enabled, container, measure, count]);

  return enabled ? fit : undefined;
}

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'OverflowList',
  group: 'Display',
  status: 'beta',
  description:
    'Row of chips or avatars that renders items up to `max` (or to the available width with `responsive`, measured by ResizeObserver) and a "+N more" button that opens a Popover listing the rest.',
  primitive: '@base-ui/react/popover',
  pattern: 'list + disclosure popover',
  keyboard: [
    ['Tab', 'Moves to the "+N more" button (and any interactive items)'],
    ['Enter / Space', 'On the "+N more" button: opens the popover with the hidden items'],
    ['Escape', 'Closes the popover and returns focus to the button'],
  ],
  tokens: ['card', 'border', 'secondary', 'muted-foreground', 'foreground', 'popover', 'focus-ring'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
